E_pv_ftest = 0.2
E_pd_le = [1.0441482779324418, 1.2379112873717106, 0.9697956713343695, 1.2289940762560922, 0.8744169343846315, 1.3146949331088085, 0.9264563404253194, 1.0063799387276593, 0.7895952016315507, 0.7835473513680467, 0.8715312989107253, 0.6203293798764272, 0.6642060060091635, 0.574977414027918, 0.7723327468846676]
