@test
def test_stats():
    assert close(PermutationDistance(20, "riemann", "pairwise").test(cov, y, None, False)[1], E_pd_pairwise, atol=1e-07)
    assert abs(PermutationDistance(20, "riemann", "pairwise").test(cov, y, None, False)[0] - E_pv_pairwise) < 1e-12
    assert close(PermutationDistance(20, "riemann", "ttest").test(cov, y, None, False)[1], E_pd_ttest, atol=1e-07)
    assert abs(PermutationDistance(20, "riemann", "ttest").test(cov, y, None, False)[0] - E_pv_ttest) < 1e-12
    assert close(PermutationDistance(20, "riemann", "ftest").test(cov, y, None, False)[1], E_pd_ftest, atol=1e-07)
    assert abs(PermutationDistance(20, "riemann", "ftest").test(cov, y, None, False)[0] - E_pv_ftest) < 1e-12
    assert close(PermutationDistance(15, "logeuclid", "ttest").test(cov, y, None, False)[1], E_pd_le, atol=1e-07)
    assert close(PermutationModel(8, MDM(), 3).test(cov, yb, None, False)[1], E_pm, atol=1e-07)
test_stats()
